/* ============ sprites.js — Mystery Dungeon style sprites (local) ============
 * SpriteCollab sheets in assets/pokemon/{dex}/{Anim}.png, geometry in
 * SPRITE_META (js/data/sprites-meta.js, generated by scripts/fetch_sprites.py).
 *
 *   columns = frames · rows = 8 directions
 *   0 Down · 1 DownRight · 2 Right · 3 UpRight · 4 Up · 5 UpLeft · 6 Left · 7 DownLeft
 *
 * Each animation has its own frame size, so they are aligned by the ground
 * anchor (ax, ay): that pixel always lands on the entity's feet and the
 * sprite doesn't "jump" when switching from Walk to Attack.
 */
import { U } from './util.js';
import { SPRITE_META } from '../data/sprites-meta.js';

export const Sprites = (() => {
  /** World units per art pixel. Tiles and sprites share the scale. */
  const PX = 2;
  const sheets = new Map(); // "dex/Anim[/s]" -> {img, ready, failed}

  function meta(dex) {
    return SPRITE_META[dex] || null;
  }

  /** Does it float in its sprite? (scripts/hover_flags.py) It passes over rocks and water. */
  function hovers(dex) {
    const m = meta(dex);
    return !!(m && m.hv);
  }

  /**
   * White version of an image (for the flash when taking a hit).
   * Made once per sheet with "source-in" compositing: much cheaper than
   * ctx.filter on every draw, which was the biggest slowdown with many
   * enemies at once.
   */
  const whites = new WeakMap();
  function white(img) {
    let c = whites.get(img);
    if (c) return c;
    c = document.createElement('canvas');
    c.width = img.width;
    c.height = img.height;
    const x = c.getContext('2d');
    x.drawImage(img, 0, 0);
    x.globalCompositeOperation = 'source-in';
    x.fillStyle = '#ffffff';
    x.fillRect(0, 0, c.width, c.height);
    whites.set(img, c);
    return c;
  }

  /** Does it have a shiny version? (assets/pokemon/{dex}/s/) */
  function hasShiny(dex) {
    const m = meta(dex);
    return !!(m && m.sh);
  }

  /** Animations available for that variant. */
  function has(m, anim, shiny) {
    return !!m.a[anim] && !(shiny && m.sm && m.sm.includes(anim));
  }

  function animName(dex, anim, shiny = false) {
    const m = meta(dex);
    if (!m) return null;
    shiny = shiny && !!m.sh;
    if (has(m, anim, shiny)) return anim;
    return has(m, 'Idle', shiny) ? 'Idle' : 'Walk';
  }

  /** An animation's geometry (the shiny one only differs in rare cases). */
  function animMeta(dex, anim, shiny = false) {
    const m = meta(dex);
    if (!m) return null;
    const name = animName(dex, anim, shiny);
    if (shiny && m.sh && m.sa && m.sa[name]) return m.sa[name];
    return m.a[name] || null;
  }

  // Maximum sheets in memory. None used to be released: in runs longer than
  // an hour hundreds of species went by, graphics memory filled up and the
  // screen went black until the browser reloaded the page.
  const MAX_SHEETS = 200,
    IDLE_MS = 20000; // ~0.66 MB each once drawn: ~130 MB
  function evict(now) {
    const old = [...sheets].filter(([, s]) => now - s.at > IDLE_MS).sort((a, b) => a[1].at - b[1].at);
    const drop = old.slice(0, Math.max(sheets.size - Math.floor(MAX_SHEETS * 0.75), 0));
    for (const [k, s] of drop) {
      sheets.delete(k);
      s.img.onload = s.img.onerror = null;
      s.img.src = ''; // release the decoded image
    }
  }

  function sheet(dex, anim, shiny = false) {
    const m = meta(dex);
    shiny = shiny && !!(m && m.sh);
    const name = animName(dex, anim, shiny);
    if (!name) return null;
    const k = dex + '/' + name + (shiny ? '/s' : '');
    let s = sheets.get(k);
    const now = Date.now();
    if (s) {
      s.at = now;
      // If the download failed (bad network, overloaded server), retry later.
      if (s.failed && performance.now() > s.retryAt) {
        s.failed = false;
        s.img.src = s.src + '?r=' + s.tries;
      }
      return s;
    }
    if (sheets.size >= MAX_SHEETS) evict(now);
    s = {
      ready: false,
      failed: false,
      img: new Image(),
      tries: 0,
      retryAt: 0,
      at: now,
      src: `assets/pokemon/${dex}/${shiny ? 's/' : ''}${name}.png`
    };
    s.img.onload = () => {
      s.ready = true;
    };
    s.img.onerror = () => {
      s.failed = true;
      s.retryAt = performance.now() + 1000 * Math.min(8, 2 ** s.tries++);
    };
    s.img.src = s.src;
    sheets.set(k, s);
    return s;
  }

  const ANIMS = ['Idle', 'Walk', 'Attack', 'Shoot', 'Charge', 'Hurt', 'Faint'];

  /** Preloads all animations of those Pokémon. */
  function preload(dexes, timeout = 8000, shiny = false) {
    const hs = [];
    for (const d of dexes)
      for (const a of ANIMS) {
        const s = sheet(d, a, shiny);
        if (s) hs.push(s);
      }
    return new Promise(res => {
      const t0 = performance.now();
      (function check() {
        if (hs.every(h => h.ready || h.failed) || performance.now() - t0 > timeout) return res();
        setTimeout(check, 50);
      })();
    });
  }

  /** Screen angle (atan2(dy,dx)) -> direction row 0..7. */
  function dirFromAngle(a) {
    return ((Math.round((Math.PI / 2 - a) / (Math.PI / 4)) % 8) + 8) % 8;
  }

  /** Approximate collision radius from the sprite size. */
  function bodyRadius(dex, scale = 1) {
    const m = animMeta(dex, 'Idle');
    const w = m ? m.w : 32;
    return U.clamp(w * 0.22, 5, 26) * PX * scale;
  }

  /** Approximate visual height (for health bars and damage numbers). */
  function bodyHeight(dex, scale = 1) {
    const m = animMeta(dex, 'Idle');
    return (m ? m.ay : 24) * PX * scale;
  }

  /** Elliptical shadow under the feet, sized by PMD's ShadowSize. */
  function drawShadow(ctx, dex, x, y, scale = 1) {
    const m = meta(dex);
    const s = m ? m.s : 1;
    const rx = [5, 8, 12][U.clamp(s, 0, 2)] * PX * scale;
    ctx.fillStyle = 'rgba(0,0,0,.34)';
    ctx.beginPath();
    ctx.ellipse(x, y, rx, rx * 0.42, 0, 0, 6.2832);
    ctx.fill();
  }

  // ---------------- Animator ----------------

  /**
   * Plays a Pokémon's animations.
   *   loop(anim)        background animation (Idle / Walk); doesn't restart if already playing
   *   play(anim, opts)  one-shot animation (Attack, Shoot, Hurt...) that covers
   *                     the background one until it ends
   */
  class Animator {
    constructor(dex, scale = 1, shiny = false) {
      this.dex = dex;
      this.shiny = shiny && hasShiny(dex);
      this.scale = scale;
      this.base = 'Idle';
      this.cur = 'Idle';
      this.frame = 0;
      this.t = 0; // time within the frame, in 1/60 s
      this.speed = 1;
      this.once = false;
      this.hold = false; // stays on the last frame (Faint)
      this.done = false;
      this.dir = 0;
      // Sheets load when first drawn; the run preloads them all with
      // preload() so they don't flicker on the first attack.
    }

    loop(anim, speed = 1) {
      this.base = anim;
      if (!this.once && this.cur !== anim) this._start(anim, false);
      if (!this.once) this.speed = speed;
    }

    /** opts: { speed, hold } */
    play(anim, opts = {}) {
      this._start(anim, true);
      this.speed = opts.speed || 1;
      this.hold = !!opts.hold;
    }

    /** Is a one-shot animation still playing? */
    busy() {
      return this.once && !this.done;
    }

    /** Progress 0..1 of the current animation. */
    progress() {
      const m = animMeta(this.dex, this.cur, this.shiny);
      if (!m) return 1;
      let total = 0,
        before = 0;
      for (let i = 0; i < m.n; i++) {
        if (i < this.frame) before += m.d[i];
        total += m.d[i];
      }
      return total ? (before + this.t) / total : 1;
    }

    _start(anim, once) {
      this.cur = animName(this.dex, anim, this.shiny) || 'Idle';
      this.frame = 0;
      this.t = 0;
      this.once = once;
      this.done = false;
    }

    update(dt) {
      const m = animMeta(this.dex, this.cur, this.shiny);
      if (!m || this.done) return;
      this.t += dt * 60 * this.speed;
      while (this.t >= m.d[this.frame]) {
        this.t -= m.d[this.frame];
        this.frame++;
        if (this.frame >= m.n) {
          if (this.once) {
            if (this.hold) {
              this.frame = m.n - 1;
              this.done = true;
              return;
            }
            // Back to the background animation.
            this._start(this.base, false);
            this.speed = 1;
            return;
          }
          this.frame = 0;
        }
      }
    }

    /** Draws with the feet at (x, y). opts: { flash, alpha } */
    draw(ctx, x, y, opts = {}) {
      let m = animMeta(this.dex, this.cur, this.shiny);
      let s = sheet(this.dex, this.cur, this.shiny);
      const k = PX * this.scale;
      if (s && !s.ready) {
        // While this animation loads, show Idle if it's ready.
        const idle = sheet(this.dex, 'Idle', this.shiny);
        if (idle && idle.ready) {
          s = idle;
          m = animMeta(this.dex, 'Idle', this.shiny);
        }
      }
      const frame = s === sheet(this.dex, this.cur, this.shiny) ? this.frame : 0;
      if (!m || !s || !s.ready) {
        // Fallback: a little ball, in case the file is missing.
        ctx.fillStyle = opts.color || '#6b7a94';
        ctx.beginPath();
        ctx.arc(x, y - 12 * k, 8 * k, 0, 6.2832);
        ctx.fill();
        return;
      }
      const row = Math.min(this.dir, m.r - 1);
      const alpha = opts.alpha == null ? 1 : opts.alpha;
      if (alpha <= 0) return;
      const sx = Math.min(frame, m.n - 1) * m.w,
        sy = row * m.h;
      const dx = Math.round(x - m.ax * k),
        dy = Math.round(y - m.ay * k);
      const prev = ctx.globalAlpha;
      if (alpha < 1) ctx.globalAlpha = prev * alpha;
      // Flash: fully white (enemies) or half white on top (your Pokémon).
      if (!opts.flash || opts.softFlash) ctx.drawImage(s.img, sx, sy, m.w, m.h, dx, dy, m.w * k, m.h * k);
      if (opts.flash) {
        if (opts.softFlash) ctx.globalAlpha = prev * alpha * 0.55;
        ctx.drawImage(white(s.img), sx, sy, m.w, m.h, dx, dy, m.w * k, m.h * k);
      }
      ctx.globalAlpha = prev;
    }
  }

  return {
    PX,
    meta,
    hasShiny,
    hovers,
    white,
    animMeta,
    sheet,
    preload,
    dirFromAngle,
    bodyRadius,
    bodyHeight,
    drawShadow,
    Animator,
    ANIMS,
    get sheetCount() {
      return sheets.size;
    }
  };
})();
